const softDeleteCombo = `-- name: SoftDeleteCombo :execrows
UPDATE combos
SET deleted_at = now(),
    updated_at = now()
WHERE id = $1
  AND deleted_at IS NULL
`

// SoftDeleteCombo
//
//	UPDATE combos
//	SET deleted_at = now(),
//	    updated_at = now()
//	WHERE id = $1
//	  AND deleted_at IS NULL
func (q *Queries) SoftDeleteCombo(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.ExecContext(ctx, softDeleteCombo, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateCombo = `-- name: UpdateCombo :one
UPDATE combos
SET name        = $2,
    slug        = $3,
    price_cents = $4,
    starts_at   = $5,
    ends_at     = $6,
    is_active   = $7,
    updated_at  = now()
WHERE id = $1
  AND deleted_at IS NULL
RETURNING id, name, slug, price_cents, starts_at, ends_at, is_active, created_at, updated_at, deleted_at
`

type UpdateComboParams struct {
	ID         uuid.UUID `db:"id" json:"id"`
	Name       string    `db:"name" json:"name"`
	Slug       string    `db:"slug" json:"slug"`
	PriceCents int64     `db:"price_cents" json:"priceCents"`
	StartsAt   time.Time `db:"starts_at" json:"startsAt"`
	EndsAt     time.Time `db:"ends_at" json:"endsAt"`
	IsActive   bool      `db:"is_active" json:"isActive"`
}

// UpdateCombo
//
//	UPDATE combos
//	SET name        = $2,
//	    slug        = $3,
//	    price_cents = $4,
//	    starts_at   = $5,
//	    ends_at     = $6,
//	    is_active   = $7,
//	    updated_at  = now()
//	WHERE id = $1
//	  AND deleted_at IS NULL
//	RETURNING id, name, slug, price_cents, starts_at, ends_at, is_active, created_at, updated_at, deleted_at
func (q *Queries) UpdateCombo(ctx context.Context, arg UpdateComboParams) (Combo, error) {
	row := q.db.QueryRowContext(ctx, updateCombo,
		arg.ID,
		arg.Name,
		arg.Slug,
		arg.PriceCents,
		arg.StartsAt,
		arg.EndsAt,
		arg.IsActive,
	)
	var i Combo
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.PriceCents,
		&i.StartsAt,
		&i.EndsAt,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
